"use client"
import * as React from "react"
import { motion, useMotionValue, useSpring, useReducedMotion } from "motion/react"
import { cn } from "@/lib/utils"
import { Button } from "../ui/button"

function MagneticCta({
  children = "Get started",
  className,
  strength = 28,
  ...props
}: React.ComponentProps<typeof Button> & { strength?: number }) {
  const reduce = useReducedMotion()
  const x = useMotionValue(0)
  const y = useMotionValue(0)
  const sx = useSpring(x, { stiffness: 220, damping: 18, mass: 0.4 })
  const sy = useSpring(y, { stiffness: 220, damping: 18, mass: 0.4 })
  const ref = React.useRef<HTMLDivElement>(null)

  const onMove = (e: React.MouseEvent) => {
    if (reduce || !ref.current) return
    const r = ref.current.getBoundingClientRect()
    const dx = e.clientX - (r.left + r.width / 2)
    const dy = e.clientY - (r.top + r.height / 2)
    x.set((dx / (r.width / 2)) * strength)
    y.set((dy / (r.height / 2)) * strength)
  }

  return (
    <motion.div
      data-slot="magnetic-cta"
      data-tier="premium"
      ref={ref}
      onMouseMove={onMove}
      onMouseLeave={() => { x.set(0); y.set(0) }}
      style={reduce ? undefined : { x: sx, y: sy }}
      className={cn("inline-flex", className)}>
      <Button type="button" className="w-full" {...props}>{children}</Button>
    </motion.div>
  )
}
export { MagneticCta }

"use client"
import * as React from "react"
import { motion, useReducedMotion } from "motion/react"
import { cn } from "@/lib/utils"

function DeviceFrameStack({ className }: { className?: string }) {
  const reduce = useReducedMotion()
  const frames = [
    { rotate: -5, x: -22, y: 14, z: 0, label: "Mobile" },
    { rotate: 0, x: 0, y: 0, z: 1, label: "App" },
    { rotate: 4, x: 26, y: 16, z: 0, label: "Docs" },
  ]
  return (
    <div
      data-slot="device-frame-stack"
      data-tier="premium"
      className={cn(
        "relative mx-auto flex h-64 w-full max-w-lg items-center justify-center overflow-hidden sm:h-72",
        className
      )}
    >
      {frames.map((f, i) => (
        <motion.div
          key={f.label}
          initial={reduce ? false : { y: 30, rotate: 0 }}
          whileInView={{ y: f.y, rotate: f.rotate, x: f.x }}
          viewport={{ once: true }}
          transition={{ delay: 0.1 + i * 0.08, type: "spring", stiffness: 120, damping: 16 }}
          style={{ zIndex: f.z + 1 }}
          className="absolute w-36 overflow-hidden rounded-xl border border-border bg-surface shadow-highlight sm:w-44"
        >
          <div className="flex h-7 items-center gap-1 border-b border-border bg-sunken px-2">
            <span className="size-1.5 rounded-full bg-fg-subtle/50" />
            <span className="size-1.5 rounded-full bg-fg-subtle/50" />
            <span className="size-1.5 rounded-full bg-fg-subtle/50" />
            <span className="ml-2 truncate text-[10px] text-fg-muted">{f.label}</span>
          </div>
          <div className="space-y-2 p-3">
            <div className="h-2 w-3/4 rounded bg-fg/10" />
            <div className="h-2 w-1/2 rounded bg-fg/5" />
            <div className="mt-2 aspect-video rounded-md border border-border bg-[radial-gradient(circle_at_40%_30%,color-mix(in_oklch,var(--accent)_22%,transparent),transparent_65%)] bg-sunken" />
